#include<limits.h>
/*@
assigns \nothing;
ensures INT_MIN <= \result < INT_MAX;
*/
int unknown();
#define N 10000
#define fun mapavg
#include <assert.h>
int mapavg (int x[N])
{
  int i;
  long long ret;
  /*
  loop invariant 0 <= i <= N;
  loop invariant ret >= 0;
  loop invariant ret <= i * (2 * INT_MAX + N);
  loop assigns i, ret;
  loop variant N - i;
  */
  ret = 0;
  for (i = 0; i < N; i++) {
    ret = ret+ i + x[i];
  }
  return ret / N;
}
int main ()
{
  int x[N];
  int temp;
  int ret, ret2, ret5;
  for (int i = 0; i < N; i++) {
    x[i] = unknown();
  }
  ret = fun(x);
  temp=x[0];x[0] = x[1]; x[1] = temp;
  ret2 = fun(x);
  temp=x[0];
  for(int i =0 ; i<N-1; i++){
     x[i] = x[i+1];
  }
  x[N-1] = temp;
  ret5 = fun(x);
  // Both swaps and rotations preserve the sum sufficiently that division by N yields equality
  //@ assert !(ret != ret2 || ret !=ret5);
  return 1;
}
